import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
    except StopIteration:
        return

    L = [0] * N
    R = [0] * N

    for i in range(N):
        L[i] = int(next(iterator))
        R[i] = int(next(iterator))

    total_sum = 0
    col_counts = [0] * (N + 1)

    for i in range(N):
        count = R[i] - L[i] + 1
        total_sum += count
        for c in range(L[i], R[i] + 1):
            col_counts[c] += 1

    try:
        Q_str = next(iterator)
        Q = int(Q_str)
    except StopIteration:
        Q = 0

    results = []

    for _ in range(Q):
        x = int(next(iterator))
        y = int(next(iterator))

        x_idx = x - 1
        y_idx = y

        row_x_count = R[x_idx] - L[x_idx] + 1
        intersection = 1 if (L[x_idx] <= y_idx <= R[x_idx]) else 0

        current_sum = total_sum - row_x_count - col_counts[y_idx] + intersection

        if current_sum % 2 == 0:
            results.append('E')
        else:
            results.append('O')

    print('\n'.join(results))

if __name__ == "__main__":
    main()
